def last_occurrence_indices(seq):
    result = {}
    for i, x in enumerate(seq):
        result[x] = i
    return result

def group_indices_in_range(seq, low, high):
    result = {}
    for i, x in enumerate(seq):
        if low <= x <= high:
            result.setdefault(x, []).append(i)
    return result

def least_common_element(seq):
    if not seq:
        return None
    counts = {}
    for x in seq:
        counts[x] = counts.get(x, 0) + 1
    min_count = min(counts.values())
    candidates = [k for k, c in counts.items() if c == min_count]
    return min(candidates)

def rename_keys(d, mapping):
    result = {}
    for k, v in d.items():
        new_key = mapping.get(k, k)
        result[new_key] = v
    return result

def rename_keys_records(records, mapping):
    result = []
    for d in records:
        renamed = {}
        for k, v in d.items():
            new_key = mapping.get(k, k)
            renamed[new_key] = v
        result.append(renamed)
    return result

def group_by_first_element(pairs):
    result = {}
    for a, b in pairs:
        result.setdefault(a, []).append(b)
    return result

def count_by_string_length(strings):
    result = {}
    for s in strings:
        length = len(s)
        result[length] = result.get(length, 0) + 1
    return result

def dedupe_keep_max(pairs):
    result = {}
    for name, score in pairs:
        if name not in result or score > result[name]:
            result[name] = score
    return result

def longest_keys(d):
    if not d:
        return []
    max_len = max(len(k) for k in d)
    return sorted(k for k in d if len(k) == max_len)

def key_with_longest_list(d):
    max_len = max(len(v) for v in d.values())
    candidates = [k for k, v in d.items() if len(v) == max_len]
    return min(candidates)

def sparse_to_dense(sparse, length):
    result = [0] * length
    for idx, val in sparse.items():
        if 0 <= idx < length:
            result[idx] = val
    return result

def invert_unique_tags(d):
    result = {}
    for k, tags in d.items():
        for tag in tags:
            result[tag] = k
    return result

def pad_left(s, width):
    if len(s) >= width:
        return s
    return ' ' * (width - len(s)) + s

def pad_right(s, width):
    if len(s) >= width:
        return s
    return s + ' ' * (width - len(s))

def zero_pad_number(n, width):
    if n < 0:
        digits = str(-n)
        if len(digits) >= width:
            return '-' + digits
        return '-' + digits.zfill(width)
    else:
        s = str(n)
        if len(s) >= width:
            return s
        return s.zfill(width)

def center_text_block(lines, width):
    result = []
    for line in lines:
        total_pad = width - len(line)
        if total_pad <= 0:
            result.append(line)
        else:
            left = total_pad // 2
            right = total_pad - left
            result.append(' ' * left + line + ' ' * right)
    return result

def pad_hex(n, width):
    s = format(n, 'X')
    if len(s) >= width:
        return s
    return s.zfill(width)
